import time
import logging
from taf.internal.managedobject import ManagedObject
from taf.internal.portforwarding.exceptions import TimeoutError


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Sshd(ManagedObject):

    def __init__(self,
                 ssh_connection,
                 port,
                 sudo_prefix="sudo ",
                 **kwargs):
        super(Sshd, self).__init__(**kwargs)

        self._ssh_connection = ssh_connection
        self.add_prerequisite(self._ssh_connection)

        self._port = port
        self._host = self._ssh_connection.address.host
        self._sudo_prefix = sudo_prefix
        self._pid_file = "/tmp/sshd_{port}.pid".format(port=port)
        self._command = ('{sudo_prefix}'
                         '/usr/sbin/sshd '
                         '-f /dev/null '
                         '-o "PermitRootLogin yes" '
                         '-o "AllowTcpForwarding yes" '
                         """-o 'PidFile "{pid_file}"' """
                         '-o "ListenAddress {host}:{port}" '
                         '-o "HostKey /etc/ssh/ssh_host_rsa_key"').format(
                             sudo_prefix=sudo_prefix,
                             pid_file=self._pid_file,
                             host=self._host,
                             port=port)

    def _setup(self):
        stdout_data = self._ssh_connection.execute(command=self._command)
        logger.debug("stdout_data=%r", stdout_data)
        self._ssh_connection.wait_until_listen(host=self._host, port=self._port)

    def _teardown(self):
        self._ssh_connection.execute(
            command="{sudo_prefix}kill -9 $(cat '{pid_file}')".format(
                sudo_prefix=self._sudo_prefix,
                pid_file=self._pid_file))


class LxcSshd(ManagedObject):

    _ATTACH_CONTAINER = " lxc-attach -n {container_id}"

    _TRY_LISTEN_TIMES = 5
    _TRY_WAITTING_TIME = 3

    _LISTEN_ADDRESS_FORMAT = 'ListenAddress {host}:{port}'

    def __init__(self,
                 ssh_connection,
                 containerid,
                 host,
                 port,
                 sudo_prefix="sudo ",
                 **kwargs):
        super(LxcSshd, self).__init__(**kwargs)

        self._ssh_connection = ssh_connection
        self._containerid = containerid
        self._host = host
        self._port = port

        self._sudo_prefix = sudo_prefix
        self._pid_file = "/tmp/sshd_{port}.pid".format(port=self._port)

        self._listen_address = self._LISTEN_ADDRESS_FORMAT.format(host=self._host, port=self._port)

        self._command = ('{sudo_prefix}'
                         '/usr/sbin/sshd '
                         '-f /dev/null '
                         '-o "PermitRootLogin yes" '
                         '-o "AllowTcpForwarding yes" '
                         """-o 'PidFile "{pid_file}"' """
                         '-o "{listen_address}" '
                         '-o "HostKey /etc/ssh/ssh_host_rsa_key"').format(
                             sudo_prefix=sudo_prefix,
                             pid_file=self._pid_file,
                             listen_address=self._listen_address)

        self._invoke_shell = None

    def _setup(self):
        self._invoke_shell = self._ssh_connection.invoke_shell()

        output = self._ssh_connection.invoke_shell_execute(self._get_lxc_attach(), invoke_shell=self._invoke_shell)
        logger.debug(output)

        output = self._ssh_connection.invoke_shell_execute(self._command, invoke_shell=self._invoke_shell)
        logger.debug("startup sshd '{}' output='{}'".format(self._command, output))

        self._check_if_sshd_process_is_running()

    def _check_if_sshd_process_is_running(self):
        try_times = self._TRY_LISTEN_TIMES
        while try_times:
            command = 'ps -ef | grep -c "{}"'.format(self._listen_address)

            output = self._ssh_connection.invoke_shell_execute(command, invoke_shell=self._invoke_shell)
            logger.debug("search sshd '{}' output='{}'".format(command, output))
            if self._extract_sshd_process_num(output, command):
                break
            try_times -= 1
            time.sleep(self._TRY_WAITTING_TIME)

        if try_times == 0:
            raise TimeoutError("{} startup failed".format(self._command))

    @staticmethod
    def _extract_sshd_process_num(output, command):
        if command in output:
            count = output.split(command)[-1].strip().split("\n")[0].strip()
            return int(count)
        return 0

    def _get_lxc_attach(self):
        return self._ATTACH_CONTAINER.format(container_id=self._containerid)

    def _teardown(self):
        self._kill_sshd_process()
        self._invoke_shell.close()

    def _kill_sshd_process(self):
        command = self._get_kill_sshd_command()
        output = self._ssh_connection.invoke_shell_execute(command, invoke_shell=self._invoke_shell)
        logger.debug("kill sshd '{}' output={}".format(command, output))

    def _get_kill_sshd_command(self):
        return '''ps -ef | grep "%s" | grep -v "grep" | awk '{print $2}' | xargs kill -9''' % self._listen_address
